window.KORKLAR_RULES100_GPT_AR = {"q013":{"textAr":"تريد الانعطاف يسارًا من المسار الظاهر. هل يجب إعطاء إشارة الاتجاه؟","answersAr":["نعم.","لا."],"answerReasonsAr":["يجب الإشارة عند الانعطاف حتى لو كان المسار مخصصًا لليسار؛ لا تفترض أن الآخرين قرؤوا الأسهم أو عرفوا نيتك.","سهم المسار يحدد الاتجاه المسموح لكنه لا يلغي واجب تنبيه الآخرين بإشارة الانعطاف."],"explanation":"يجب الإشارة عند الانعطاف حتى لو كان المسار مخصصًا لليسار؛ لا تفترض أن الآخرين قرؤوا الأسهم أو عرفوا نيتك."},"q024":{"textAr":"في أي موقف من الآتي يكون استخدام المنبّه أنسب عند الحاجة إلى التنبيه لتفادي خطر؟","answersAr":["عندما يسير شخصان على دراجتين جنبًا إلى جنب.","عندما لا تتحرك المركبة أمامي فور ظهور الضوء الأخضر.","عندما تقود المركبة أمامي بسرعة منخفضة.","عندما أريد تجاوز راكب حصان."],"answerReasonsAr":["إذا لم ينتبه الراكبان لاقترابك وكان هناك خطر، فقد يفيد تنبيه قصير مع ترك مسافة. سيرهما جنبًا إلى جنب لا يبيح المنبّه تلقائيًا لمجرد الاستعجال.","تأخر الانطلاق وحده ليس خطرًا يبرر الضغط على السائق؛ قد يكون ينتظر زوال عائق لا تراه.","السرعة المنخفضة وحدها لا تبرر المنبّه؛ قد تفرضها الرؤية أو حالة الطريق.","الصوت قد يفزع الحصان ويسبب حركة مفاجئة؛ خفف السرعة واترك مسافة جانبية كبيرة، ولا تستخدم المنبّه لمجرد التجاوز."],"explanation":"إذا لم ينتبه الراكبان لاقترابك وكان هناك خطر، فقد يفيد تنبيه قصير مع ترك مسافة. سيرهما جنبًا إلى جنب لا يبيح المنبّه تلقائيًا لمجرد الاستعجال."},"q046":{"textAr":"أنت في الموقف الظاهر في الصورة. كيف ينبغي أن تتصرف؟","answersAr":["أبقى في مسار التسارع لأطول وقت ممكن.","أكيّف سرعتي مع حركة المرور وأغادر مسار التسارع في أقرب فرصة آمنة.","أتوقف وأعطي الأولوية لجميع المركبات الأخرى."],"explanation":"استعمل المسار لمواءمة سرعتك مع المرور، راقب المرايا والنقطة العمياء، ثم اندمج عندما يتاح ذلك دون خطر.","answerReasonsAr":["البقاء حتى نهاية المسار بلا حاجة قد يفوّت فجوة آمنة ويجعل الاندماج أصعب.","استعمل المسار لمواءمة سرعتك مع المرور، راقب المرايا والنقطة العمياء، ثم اندمج عندما يتاح ذلك دون خطر.","التوقف ليس الإجراء المعتاد في مسار التسارع؛ قد يصعب بعده الاندماج. توقف فقط إذا فرضت السلامة ذلك."]},"q069":{"textAr":"ستعبر معبرًا للدراجات غير منظّم بإشارة ضوئية. ما التصرف الصحيح؟","answersAr":["أكيّف السرعة بحيث لا أعرّض راكبي الدراجات والفئة II الموجودين على المعبر للخطر.","أطبّق قاعدة اليمين فقط."],"answerReasonsAr":["خفض السرعة وحماية العابرين صحيحان. وفق التنظيم الحالي، إذا كان معبر دراجات محددًا بعلامة خاصة فعليك إعطاء الأولوية أيضًا لمن يوشك على دخوله؛ أما ممر الدراجات غير المعلّم بتلك العلامة فتختلف قواعده.","لا تُحسم هذه الحالة بقاعدة اليمين؛ نوع المعبر وعلاماته، وهل تنعطف أو تخرج من دوار، هي ما يحدد واجبك."],"explanation":"خفض السرعة وحماية العابرين صحيحان. وفق التنظيم الحالي، إذا كان معبر دراجات محددًا بعلامة خاصة فعليك إعطاء الأولوية أيضًا لمن يوشك على دخوله؛ أما ممر الدراجات غير المعلّم بتلك العلامة فتختلف قواعده."},"q098":{"textAr":"أي علامة مرورية لها علامة خاصة بانتهاء سريانها؟","answersAr":["العلامة A","العلامة B","العلامة C"],"explanation":"B بداية منطقة السير بسرعة المشي، ولها علامة نهاية مستقلة؛ داخلها تُراعى أولوية المشاة والسرعة المنخفضة جدًا.","answerReasonsAr":["A مسار للدراجات، وليس منطقة السير بسرعة المشي التي لها علامة النهاية المقصودة.","B بداية منطقة السير بسرعة المشي، ولها علامة نهاية مستقلة؛ داخلها تُراعى أولوية المشاة والسرعة المنخفضة جدًا.","C حد سرعة 50؛ يُغيّر عادةً بعلامة حد سرعة أخرى. ليست علامة منطقة السير التي ينهيها نظيرها المشطوب."],"learningSource":{"label":"هيئة النقل السويدية — العلامات المرورية","url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/"}},"q133":{"textAr":"أنت تقود السيارة E وستعبر رصيف مشاة مرتفعًا قبل دخول الطريق. ما القاعدة؟","answersAr":["على سائق السيارة A إعطائي الأولوية وفق قاعدة اليمين.","يجب عليّ إعطاء السيارة A الأولوية وفق قاعدة الخروج إلى الطريق."],"answerReasonsAr":["كونك على يمين السيارة الأخرى لا يكفي؛ دخول الطريق بعد عبور رصيف المشاة يخضع لقاعدة الخروج.","عندما تدخل الطريق بعد عبور رصيف مشاة أو مسار دراجات، تُعطي الأولوية لمستخدمي الطريق الذي تدخل إليه، وكذلك لا تعرقل المشاة على الرصيف."],"explanation":"عندما تدخل الطريق بعد عبور رصيف مشاة أو مسار دراجات، تُعطي الأولوية لمستخدمي الطريق الذي تدخل إليه، وكذلك لا تعرقل المشاة على الرصيف."},"q004":{"textAr":"ما السرعة القصوى المسموحة لشاحنة ثقيلة موصولة بمقطورة على هذا الطريق؟","answersAr":["70 كم/ساعة.","80 كم/ساعة.","90 كم/ساعة.","100 كم/ساعة."],"answerReasonsAr":["يمكن أن تفرض الظروف سرعة أقل، لكن 70 ليست الحد الأقصى لهذه المجموعة على الطريق المعروض.","الشاحنة الثقيلة مع مقطورة حدّها 80 كم/ساعة، حتى عندما تسمح علامة الطريق بسرعة أعلى. يُطبّق دائمًا الحد الأقل بين حد المركبة وحد الطريق.","90 قد يُسمح بها للشاحنة الثقيلة دون مقطورة على طريق سريع أو طريق مخصص للمركبات؛ لا تنطبق هنا مع المقطورة.","علامة 100 للطريق لا تلغي الحد الخاص بالشاحنة مع المقطورة وهو 80."],"explanation":"الشاحنة الثقيلة مع مقطورة حدّها 80 كم/ساعة، حتى عندما تسمح علامة الطريق بسرعة أعلى. يُطبّق دائمًا الحد الأقل بين حد المركبة وحد الطريق."},"q006":{"textAr":"أي علامة تخص التقاطع التالي وينتهي أثرها بعده؟","answersAr":["العلامة A.","العلامة B.","العلامة C."],"answerReasonsAr":["حد السرعة 50 لا ينتهي تلقائيًا عند التقاطع؛ يبقى حتى يتغير وفق العلامات.","الطريق ذو الأولوية يستمر حتى علامة نهايته أو تنظيم يغيّره؛ التقاطع وحده لا ينهيه.","منع الانعطاف يسارًا يخص التقاطع الذي تشير إليه العلامة؛ لا يعني منع اليسار في جميع التقاطعات الطريق التالية."],"explanation":"منع الانعطاف يسارًا يخص التقاطع الذي تشير إليه العلامة؛ لا يعني منع اليسار في جميع التقاطعات الطريق التالية."},"q007":{"textAr":"ماذا تعني هذه العلامة؟","answersAr":["تحذير من مرسى عبّارة أو رصيف على حافة الماء.","تحذير من فتح جسر عند بوابة مائية.","ممنوع تجاوز العلامة.","يجب توقع طريق زلق."],"answerReasonsAr":["الرسم يحذر من حافة تؤدي إلى الماء؛ استعد للتوقف ولا تقترب بسرعة. اللوحة 150 م تحدد المسافة إلى الخطر.","الجسر المتحرك له رسم جسر مرفوع، وليس مركبة عند حافة الماء.","هذه علامة تحذير وليست منع مرور؛ يمكنك المتابعة فقط بما يناسب الخطر.","الانزلاق له علامة مختلفة؛ الخطر المحدد هنا هو المرسى أو الرصيف عند الماء."],"explanation":"الرسم يحذر من حافة تؤدي إلى الماء؛ استعد للتوقف ولا تقترب بسرعة. اللوحة 150 م تحدد المسافة إلى الخطر."},"q010":{"textAr":"تورطت في حادث وطُلب منك اسمك وعنوانك من طرف معني بالحادث. هل يجب تقديمهما؟","answersAr":["نعم، لكن للشرطة فقط.","نعم، فقط إذا كنت المتسبب في الحادث.","نعم، ولكن بعد التحدث إلى محامٍ أولًا.","نعم، بغض النظر عمن تسبب في الحادث."],"answerReasonsAr":["واجب تقديم البيانات يشمل الطرف المتضرر أو المعني، ولا يقتصر على الشرطة.","حتى الطرف غير المخطئ يجب أن يقدم البيانات المطلوبة؛ تحديد المسؤولية يأتي لاحقًا.","لا يجوز تعليق تبادل بيانات التعريف اللازمة على استشارة محامٍ أولًا.","عليك تقديم اسمك وعنوانك والمعلومات اللازمة للطرف المعني عند طلبها. هذا لا يعني الاعتراف بالخطأ، ولا منح البيانات لأي شخص لا علاقة له بالحادث."],"explanation":"عليك تقديم اسمك وعنوانك والمعلومات اللازمة للطرف المعني عند طلبها. هذا لا يعني الاعتراف بالخطأ، ولا منح البيانات لأي شخص لا علاقة له بالحادث."},"q012":{"textAr":"تقترب من التقاطع الظاهر. لمن يجب إعطاء الأولوية؟","answersAr":["لكل المركبات القادمة من الطريق المتقاطع.","للمركبات القادمة من اليمين.","للمركبات القادمة من اليسار فقط."],"answerReasonsAr":["علامة التحذير ذات الصليب لا تعني إعطاء الأولوية للجميع؛ إنها تقاطع تطبق فيه قاعدة اليمين.","عند هذا التقاطع تطبق قاعدة اليمين؛ خفف السرعة واسمح للقادمين من يمينك بالمرور.","قاعدة اليمين تعني العكس؛ القادم من اليسار هو الذي يفسح لك، مع بقاء الحذر واجبًا."],"explanation":"عند هذا التقاطع تطبق قاعدة اليمين؛ خفف السرعة واسمح للقادمين من يمينك بالمرور."},"q018":{"textAr":"تريد الانعطاف يمينًا. ما القاعدة عند العلامة الظاهرة؟","answersAr":["يجب التوقف الكامل دائمًا.","يجب إعطاء الأولوية لكل مستخدمي الطريق المتقاطع الذين قد تتعارض معهم حركتي.","يجب إعطاء الأولوية للقادمين من اليسار فقط."],"answerReasonsAr":["علامة «الأولوية لتفريغ الطريق» (Väjningsplikt، مثلث مقلوب برأس للأسفل وحدود حمراء) لا تفرض توقفًا كاملاً إلزاميًا؛ التوقف الكامل الإجباري يكون فقط عند علامة STOP (Stopplikt). يكفي هنا تخفيف السرعة مبكرًا، والتوقف فعليًا فقط إذا استدعى الأمر ذلك لإفساح الطريق بأمان.","العلامة الموجودة في الصورة هي علامة «الأولوية لتفريغ الطريق» (Väjningsplikt / B1، مثلث مقلوب برأس للأسفل وحدود حمراء). هذه العلامة تُلزمك بإعطاء الأولوية لكل السيارات القادمة على الطريق المتقاطع، من اليمين ومن اليسار معًا، وليس لجهة واحدة فقط. كما أنها لا تشترط توقفًا كاملاً إجباريًا مثل علامة STOP، بل يكفي تخفيف السرعة مبكرًا والتوقف فقط إذا استدعى الأمر ذلك. وحتى مع نيتك الانعطاف يمينًا، فإن ذلك لا يعفيك من مراقبة الجهتين، لأن مسارك قد يتقاطع مع حركة قادمة من أي منهما.","علامة «الأولوية لتفريغ الطريق» تُلزمك بإعطاء الأولوية لحركة المرور القادمة من الطريق المتقاطع من الجهتين معًا (اليمين واليسار)، وليس من جهة اليسار فقط."],"explanation":"العلامة الموجودة في الصورة هي علامة «الأولوية لتفريغ الطريق» (Väjningsplikt / B1، مثلث مقلوب برأس للأسفل وحدود حمراء). هذه العلامة تُلزمك بإعطاء الأولوية لكل السيارات القادمة على الطريق المتقاطع، من اليمين ومن اليسار معًا، وليس لجهة واحدة فقط. كما أنها لا تشترط توقفًا كاملاً إجباريًا مثل علامة STOP، بل يكفي تخفيف السرعة مبكرًا والتوقف فقط إذا استدعى الأمر ذلك. وحتى مع نيتك الانعطاف يمينًا، فإن ذلك لا يعفيك من مراقبة الجهتين، لأن مسارك قد يتقاطع مع حركة قادمة من أي منهما."},"q020":{"textAr":"متى يجوز استخدام أضواء التحذير الرباعية؟","answersAr":["عند الركن بجانب سيارة مركونة.","بدل أضواء الوقوف بعد التوقف خارج المنطقة المأهولة.","عندما أضطر للتوقف في مكان خطر، مثل ما قبل منعطف محجوب الرؤية."],"answerReasonsAr":["التحذير لا يجعل الركن المزدوج مسموحًا.","أضواء التحذير لا تستبدل الإضاءة الواجبة لإظهار المركبة في الظلام.","التوقف الاضطراري في مكان يصعب اكتشافه يعرض الآخرين للخطر؛ التحذير ينبههم، مع اتخاذ وسائل التأمين الأخرى المناسبة."],"explanation":"التوقف الاضطراري في مكان يصعب اكتشافه يعرض الآخرين للخطر؛ التحذير ينبههم، مع اتخاذ وسائل التأمين الأخرى المناسبة."},"q022":{"textAr":"تريد الانعطاف يسارًا باتجاه لاندسكرونا. أين تتموضع قبل الانعطاف؟","answersAr":["عند أقصى يسار الطريق.","قرب منتصف الطريق في جهتي من السير.","عند أقصى يمين الطريق."],"answerReasonsAr":["هذا طريق ذو اتجاهين؛ أقصى اليسار قد يضعك في جهة المرور المقابل.","اقترب من خط الوسط دون تجاوزه، وأشر مبكرًا وأعط الأولوية حسب العلامة قبل الانعطاف.","أقصى اليمين لا يوضح نية الانعطاف يسارًا ويجعل المناورة أعرض وأكثر تعارضًا مع الآخرين."],"explanation":"اقترب من خط الوسط دون تجاوزه، وأشر مبكرًا وأعط الأولوية حسب العلامة قبل الانعطاف."},"q196":{"textAr":"تريد الانعطاف يسارًا باتجاه لاندسكرونا. أين تتموضع قبل الانعطاف؟","answersAr":["عند أقصى يسار الطريق.","قرب منتصف الطريق في جهتي من السير.","عند أقصى يمين الطريق."],"answerReasonsAr":["هذا طريق ذو اتجاهين؛ أقصى اليسار قد يضعك في جهة المرور المقابل.","اقترب من خط الوسط دون تجاوزه، وأشر مبكرًا وأعط الأولوية حسب العلامة قبل الانعطاف.","أقصى اليمين لا يوضح نية الانعطاف يسارًا ويجعل المناورة أعرض وأكثر تعارضًا مع الآخرين."],"explanation":"اقترب من خط الوسط دون تجاوزه، وأشر مبكرًا وأعط الأولوية حسب العلامة قبل الانعطاف."},"q023":{"textAr":"تعبر دراجة على مسار دراجات يمر أمامك قبل دخولك الطريق. أي قاعدة تنطبق؟","answersAr":["قاعدة الخروج إلى الطريق، لأنني سأعبر مسار الدراجات أولًا.","قاعدة اليمين.","كل تقاطع على شكل T يفرض دائمًا إعطاء الأولوية للقادمين على الطريق الآخر."],"answerReasonsAr":["دخول الطريق بعد عبور مسار دراجات يخضع لقاعدة الخروج؛ أفسح للدراجة ولمستخدمي الطريق الذي تدخل إليه.","هنا توجد حالة خروج تتقدم على قاعدة اليمين؛ لا تعتمد على الجهة وحدها.","شكل T وحده لا يحدد الأولوية؛ قد تسري قاعدة اليمين عند غياب علامات أو حالة خروج خاصة."],"explanation":"دخول الطريق بعد عبور مسار دراجات يخضع لقاعدة الخروج؛ أفسح للدراجة ولمستخدمي الطريق الذي تدخل إليه."},"q025":{"textAr":"تقترب من معبر سكة مزود بحواجز، ويعرض عامل الطريق علمًا أحمر. ماذا تفعل؟","answersAr":["أتوقف وأنتظر انتهاء إشارة التوقف، ثم أتأكد من أن العبور مسموح وآمن.","أتابع عبر السكة."],"answerReasonsAr":["العلم الأحمر إشارة توقف يجب احترامها. بعد انتهاء الإشارة لا تعبر إذا بقي ضوء أحمر أو حاجز مغلق أو قطار قريب.","وجود الحواجز لا يسمح بتجاهل العامل؛ قد يشير إلى خطر أو عمل لا تراه."],"explanation":"العلم الأحمر إشارة توقف يجب احترامها. بعد انتهاء الإشارة لا تعبر إذا بقي ضوء أحمر أو حاجز مغلق أو قطار قريب."},"q087":{"textAr":"تقترب من معبر سكة مزود بحواجز، ويعرض عامل الطريق علمًا أحمر. ماذا تفعل؟","answersAr":["أتوقف وأنتظر انتهاء إشارة التوقف، ثم أتأكد من أن العبور مسموح وآمن.","أتابع عبر السكة."],"answerReasonsAr":["العلم الأحمر إشارة توقف يجب احترامها. بعد انتهاء الإشارة لا تعبر إذا بقي ضوء أحمر أو حاجز مغلق أو قطار قريب.","وجود الحواجز لا يسمح بتجاهل العامل؛ قد يشير إلى خطر أو عمل لا تراه."],"explanation":"العلم الأحمر إشارة توقف يجب احترامها. بعد انتهاء الإشارة لا تعبر إذا بقي ضوء أحمر أو حاجز مغلق أو قطار قريب."},"q030":{"textAr":"ما المعنى الصحيح لهذه اللوحة الزرقاء؟","answersAr":["يُنصح بألا أتجاوز السرعة المكتوبة.","اللوحة نفسها تفرض حدًا قانونيًا لا يجوز تجاوزه."],"answerReasonsAr":["هذه سرعة موصى بها بسبب بيئة الطريق، وليست علامة الحد الدائرية. تبقى ملزمًا بالسرعة الآمنة والحد القانوني، وقد تحتاج إلى أقل من الرقم.","الحد القانوني يُعرض عادةً بدائرة حمراء وصفراء؛ لا تخلط التوصية بالحد الإلزامي، ولا تعتبر التوصية مبررًا للقيادة غير الآمنة."],"explanation":"هذه سرعة موصى بها بسبب بيئة الطريق، وليست علامة الحد الدائرية. تبقى ملزمًا بالسرعة الآمنة والحد القانوني، وقد تحتاج إلى أقل من الرقم."},"q031":{"textAr":"أي مركبة يجوز لك قيادتها برخصة B العادية؟","answersAr":["سيارة ركوب موصولة بمقطورة خفيفة ضمن حدود الرخصة.","شاحنة ثقيلة دون مقطورة.","دراجة نارية خفيفة."],"answerReasonsAr":["B تسمح بسيارة حتى 3500 كغ ومقطورة حتى 750 كغ، أو مقطورة أثقل إذا لم يتجاوز مجموع الوزنَين الإجماليَين 3500 كغ؛ راعِ أيضًا قدرة السحب الفنية.","الشاحنة الثقيلة تحتاج فئة شاحنات مناسبة مثل C1 أو C، ولا تكفي B لمجرد عدم وجود مقطورة.","الدراجة النارية الخفيفة ذات العجلتين تحتاج A1 أو فئة دراجات مناسبة؛ لا تمنح B العادية هذا الحق."],"explanation":"B تسمح بسيارة حتى 3500 كغ ومقطورة حتى 750 كغ، أو مقطورة أثقل إذا لم يتجاوز مجموع الوزنَين الإجماليَين 3500 كغ؛ راعِ أيضًا قدرة السحب الفنية."},"q045":{"textAr":"أي وثيقة يجب حملها أثناء قيادة شاحنة خفيفة داخل السويد؟","answersAr":["تقرير آخر فحص دوري.","شهادة تسجيل المركبة.","وثيقة التأمين.","رخصة القيادة."],"answerReasonsAr":["صلاحية الفحص مهمة، لكن لا يلزم حمل تقرير الفحص في السيارة عادةً.","قد تلزم شهادة التسجيل في سفر أو حالات خاصة؛ ليست الوثيقة المطلوبة في القيادة المحلية العادية هنا.","يجب وجود التأمين المطلوب، لكن حمل وثيقته ليس شرط السؤال.","يجب حمل رخصة القيادة وإبرازها عند طلب الجهة المخولة؛ لا تخلط صلاحية المركبة بالوثيقة الشخصية للسائق."],"explanation":"يجب حمل رخصة القيادة وإبرازها عند طلب الجهة المخولة؛ لا تخلط صلاحية المركبة بالوثيقة الشخصية للسائق."},"q175":{"textAr":"أي وثيقة يجب حملها أثناء قيادة شاحنة خفيفة داخل السويد؟","answersAr":["تقرير آخر فحص دوري.","شهادة تسجيل المركبة.","وثيقة التأمين.","رخصة القيادة."],"answerReasonsAr":["صلاحية الفحص مهمة، لكن لا يلزم حمل تقرير الفحص في السيارة عادةً.","قد تلزم شهادة التسجيل في سفر أو حالات خاصة؛ ليست الوثيقة المطلوبة في القيادة المحلية العادية هنا.","يجب وجود التأمين المطلوب، لكن حمل وثيقته ليس شرط السؤال.","يجب حمل رخصة القيادة وإبرازها عند طلب الجهة المخولة؛ لا تخلط صلاحية المركبة بالوثيقة الشخصية للسائق."],"explanation":"يجب حمل رخصة القيادة وإبرازها عند طلب الجهة المخولة؛ لا تخلط صلاحية المركبة بالوثيقة الشخصية للسائق."},"q059":{"textAr":"أين يجب التوقف عند معبر السكة الظاهر دون خط توقف مرسوم؟","answersAr":["على بعد عشرة أمتار قبل علامة التوقف.","مباشرة قبل موضع علامة التوقف.","مباشرة قبل دخول منطقة السكة، في موضع آمن.","لا أتوقف إلا إذا اقترب قطار."],"answerReasonsAr":["لا توجد مسافة ثابتة مقدارها عشرة أمتار من العلامة في هذه الحالة.","موضع العمود لا يحدد وحده موضع توقفك؛ عند غياب الخط توقف قبل دخول منطقة السكة مع رؤية كافية.","التوقف كامل وواجب قبل دخول منطقة السكة عند غياب خط توقف. اترك مسافة أمان من القضبان وتحقق من خلو العبور قبل التحرك.","علامة STOP تفرض التوقف حتى إذا لم تر قطارًا؛ النظر السريع أثناء السير لا يكفي."],"explanation":"التوقف كامل وواجب قبل دخول منطقة السكة عند غياب خط توقف. اترك مسافة أمان من القضبان وتحقق من خلو العبور قبل التحرك."},"q149":{"textAr":"أين يجب التوقف عند معبر السكة الظاهر دون خط توقف مرسوم؟","answersAr":["على بعد عشرة أمتار قبل علامة التوقف.","مباشرة قبل موضع علامة التوقف.","مباشرة قبل دخول منطقة السكة، في موضع آمن.","لا أتوقف إلا إذا اقترب قطار."],"answerReasonsAr":["لا توجد مسافة ثابتة مقدارها عشرة أمتار من العلامة في هذه الحالة.","موضع العمود لا يحدد وحده موضع توقفك؛ عند غياب الخط توقف قبل دخول منطقة السكة مع رؤية كافية.","التوقف كامل وواجب قبل دخول منطقة السكة عند غياب خط توقف. اترك مسافة أمان من القضبان وتحقق من خلو العبور قبل التحرك.","علامة STOP تفرض التوقف حتى إذا لم تر قطارًا؛ النظر السريع أثناء السير لا يكفي."],"explanation":"التوقف كامل وواجب قبل دخول منطقة السكة عند غياب خط توقف. اترك مسافة أمان من القضبان وتحقق من خلو العبور قبل التحرك."},"q060":{"textAr":"كيف تفسر هذه العلامة مع اللوحة الإضافية؟","answersAr":["بعد الانعطاف يمينًا يوجد معبر سكة حديد بحواجز.","للوصول إلى محطة القطار يجب الانعطاف يمينًا.","السكة موازية للطريق على يمينك فقط."],"answerReasonsAr":["رمز الحاجز يحذر من معبر سكة مزود بحواجز، والسهم يحدد أن الخطر على الطريق الذي تنعطف إليه يمينًا.","هذه علامة خطر، وليست لوحة اتجاه إلى محطة قطارات.","السهم يوجّه التحذير إلى الطريق الجانبي؛ لا يعني مجرد وجود سكة موازية."],"explanation":"رمز الحاجز يحذر من معبر سكة مزود بحواجز، والسهم يحدد أن الخطر على الطريق الذي تنعطف إليه يمينًا."},"q063":{"textAr":"من قد يُسمح له بالخروج عن قواعد موضع المركبة على الطريق عند الحاجة؟","answersAr":["سائق سيارة أجرة.","راكب دراجة هوائية.","سائق مركبة تؤدي أعمال صيانة الطريق.","سائق مركبة يزيد عرضها على 2.60 متر."],"answerReasonsAr":["عمل سيارة الأجرة لا يمنح استثناءً عامًا من قواعد موضع السير.","راكب الدراجة يتبع القواعد الخاصة به؛ ليس معفيًا عمومًا من موضع السير.","أعمال الطرق قد تتطلب السير أو الوقوف في موضع غير معتاد؛ يُسمح بالاستثناء اللازم للعمل مع حذر خاص.","كبر العرض لا يتيح مخالفة قواعد الموضع من تلقاء نفسك؛ قد يحتاج النقل إلى تصريح وشروط محددة."],"explanation":"أعمال الطرق قد تتطلب السير أو الوقوف في موضع غير معتاد؛ يُسمح بالاستثناء اللازم للعمل مع حذر خاص."},"q065":{"textAr":"تقود السيارة الزرقاء وتريد الانعطاف يمينًا، بينما يتابع راكب الموبيد مستقيمًا إلى جانبك. ما الصحيح؟","answersAr":["لا يجوز لي قطع طريق راكب الموبيد أو إعاقته عند الانعطاف.","يجب على راكب الموبيد انتظاري حتى أنعطف."],"answerReasonsAr":["افحص المرايا والنقطة العمياء وأفسح له قبل الانعطاف؛ مسارك سينقل السيارة عبر خط سيره.","إشارة انعطافك لا تمنحك الأولوية على من يسير مستقيمًا إلى جانبك."],"explanation":"افحص المرايا والنقطة العمياء وأفسح له قبل الانعطاف؛ مسارك سينقل السيارة عبر خط سيره."},"q071":{"textAr":"تقود السيارة الحمراء وإشارتك خضراء، وتقترب سيارة إسعاف طالبةً إخلاء الطريق. ما الصحيح؟","answersAr":["على الإسعاف إعطائي الأولوية لأن الضوء أخضر لي.","لا يلزمني إفساح الطريق إذا استخدمت الضوء الأزرق دون صفارة.","يجب أن أفسح الطريق للإسعاف."],"answerReasonsAr":["الضوء الأخضر لا يبرر عرقلة مركبة طوارئ تطلب المرور؛ افسح لها بأمان.","قد تطلب مركبة الطوارئ المرور بإشارة ضوئية أو صوتية؛ لا تشترط وجودهما معًا لتتعاون.","خفف السرعة وافسح مسارًا واضحًا دون خلق خطر جديد، وتوقف عند الحاجة؛ لا تندفع عبر التقاطع لمجرد إخلائه."],"explanation":"خفف السرعة وافسح مسارًا واضحًا دون خلق خطر جديد، وتوقف عند الحاجة؛ لا تندفع عبر التقاطع لمجرد إخلائه."},"q072":{"textAr":"ما الذي يجب حمله عند قيادة سيارة ركوب؟","answersAr":["تقرير آخر فحص دوري.","إثبات التأمين المروري.","رخصة القيادة.","نموذج بلاغ الحوادث."],"answerReasonsAr":["لا يلزم حمل تقرير الفحص عادةً أثناء القيادة المحلية.","التأمين واجب على المركبة عندما تنطبق شروطه، لكن لا يلزم عادةً حمل إثباته للقيادة المحلية.","الرخصة هي الوثيقة المطلوبة للسائق أثناء القيادة ويجب إبرازها عند الطلب المخوّل.","نموذج الحوادث مفيد، لكنه ليس وثيقة إلزامية لكل رحلة."],"explanation":"الرخصة هي الوثيقة المطلوبة للسائق أثناء القيادة ويجب إبرازها عند الطلب المخوّل."},"q073":{"textAr":"أي عبارة صحيحة عن قاعدة اليمين؟","answersAr":["لا تطبق داخل المواقف ومحطات الوقود والأماكن المفتوحة.","لا تطبق في التقاطعات ذات ثلاثة اتجاهات.","يجب إعطاء الأولوية لحركة المرور القادمة من اليمين عندما تسري القاعدة.","على القادم من اليمين إعطائي الأولوية."],"answerReasonsAr":["قد تطبق داخل هذه الأماكن أيضًا؛ أما الخروج منها إلى طريق فيخضع عادةً لقاعدة الخروج.","تقاطع T لا يلغي قاعدة اليمين بمجرد شكله.","عند غياب تنظيم يتقدم عليها، أفسح للقادم من يمينك؛ تظل مسؤولًا عن الحذر حتى مع أولوية مرورك.","هذا يعكس القاعدة؛ أنت من يفسح للقادم من يمينه."],"explanation":"عند غياب تنظيم يتقدم عليها، أفسح للقادم من يمينك؛ تظل مسؤولًا عن الحذر حتى مع أولوية مرورك."},"q074":{"textAr":"ماذا تمنع هذه العلامة عند التقاطع القادم؟","answersAr":["الانعطاف يسارًا والرجوع بالدوران معًا.","الانعطاف يسارًا في التقاطع فقط.","الرجوع بالدوران فقط."],"answerReasonsAr":["منع الانعطاف يسارًا ومنع الرجوع بالدوران لهما علامتان مختلفتان؛ لا تجمعهما تلقائيًا.","السهم المشطوب يحظر الانعطاف يسارًا في التقاطع. أي دوران آخر يبقى مشروطًا بالقواعد العامة والسلامة والعلامات الأخرى.","منع الرجوع بالدوران يحمل سهمًا ملتفًا للخلف، وليس السهم الظاهر هنا."],"explanation":"السهم المشطوب يحظر الانعطاف يسارًا في التقاطع. أي دوران آخر يبقى مشروطًا بالقواعد العامة والسلامة والعلامات الأخرى."},"q078":{"textAr":"تقود سيارة ركوب مع مقطورة مزودة بفرامل. ما سرعتها القصوى على الطريق السريع؟","answersAr":["70 كم/ساعة.","80 كم/ساعة.","90 كم/ساعة."],"answerReasonsAr":["70 ليست الحد الخاص المعتاد لهذه المجموعة، وإن لزم خفض السرعة إليها أو أقل بحسب الظروف أو العلامات.","الحد الخاص بسيارة مع مقطورة مفرملة هو 80 كم/ساعة؛ سرعة الطريق الأعلى لا تلغي هذا الحد.","90 تتجاوز الحد المسموح للمجموعة حتى على طريق سريع."],"explanation":"الحد الخاص بسيارة مع مقطورة مفرملة هو 80 كم/ساعة؛ سرعة الطريق الأعلى لا تلغي هذا الحد."},"q084":{"textAr":"ما السرعة الأساسية خارج المناطق المأهولة عندما لا توجد علامة أو قاعدة أخرى تحدد السرعة؟","answersAr":["50 كم/ساعة.","70 كم/ساعة.","90 كم/ساعة.","110 كم/ساعة."],"answerReasonsAr":["50 هي السرعة الأساسية داخل المنطقة المأهولة، وليست خارجها.","السرعة الأساسية خارج المنطقة المأهولة 70 كم/ساعة؛ تبقى العلامات والحدود الخاصة بالمركبة والظروف مقدمة عليها.","90 تحتاج إلى تنظيم يسمح بها؛ لا تستنتجها لمجرد الخروج من المدينة.","110 ليست سرعة أساسية لجميع الطرق الخارجية؛ تُطبق فقط حيث تسمح القواعد والعلامات."],"explanation":"السرعة الأساسية خارج المنطقة المأهولة 70 كم/ساعة؛ تبقى العلامات والحدود الخاصة بالمركبة والظروف مقدمة عليها."},"q187":{"textAr":"ما السرعة الأساسية خارج المناطق المأهولة عندما لا توجد علامة أو قاعدة أخرى تحدد السرعة؟","answersAr":["50 كم/ساعة.","70 كم/ساعة.","90 كم/ساعة.","110 كم/ساعة."],"answerReasonsAr":["50 هي السرعة الأساسية داخل المنطقة المأهولة، وليست خارجها.","السرعة الأساسية خارج المنطقة المأهولة 70 كم/ساعة؛ تبقى العلامات والحدود الخاصة بالمركبة والظروف مقدمة عليها.","90 تحتاج إلى تنظيم يسمح بها؛ لا تستنتجها لمجرد الخروج من المدينة.","110 ليست سرعة أساسية لجميع الطرق الخارجية؛ تُطبق فقط حيث تسمح القواعد والعلامات."],"explanation":"السرعة الأساسية خارج المنطقة المأهولة 70 كم/ساعة؛ تبقى العلامات والحدود الخاصة بالمركبة والظروف مقدمة عليها."},"q185":{"textAr":"كم يبلغ تقريبًا عدد وفيات المرور السنوية في السويد في هذا السؤال القديم؟","answersAr":["نحو 100.","نحو 300.","نحو 500.","نحو 700."],"answerReasonsAr":["100 ليس التقدير الذي يعتمد عليه السؤال القديم؛ عدد الوفيات يتغير سنويًا ولا يُحفظ كرقم ثابت.","300 هو الجواب الموجود في هذا السؤال القديم، وليس إحصاءً حاليًا. بلغ العدد الرسمي 203 وفيات في عام 2025؛ لذلك يجب ربط الأرقام بسنة محددة.","500 لا يطابق تقدير السؤال ولا إحصاء 2025؛ قد تعكس أرقام الأسئلة القديمة فترات مختلفة.","700 ليس رقمًا حاليًا؛ بلغ العدد 203 في عام 2025. لا تستنتج السلامة أو الخطر من رقم بلا تاريخ."],"contentNoteAr":"سؤال قديم يحتاج تحديث خياراته: الإجابة المحفوظة 300، بينما العدد الرسمي لعام 2025 هو 203. لا توجد إجابة تطابق الإحصاء الحالي بين الخيارات.","explanation":"300 هو الجواب الموجود في هذا السؤال القديم، وليس إحصاءً حاليًا. بلغ العدد الرسمي 203 وفيات في عام 2025؛ لذلك يجب ربط الأرقام بسنة محددة."},"q191":{"textAr":"متى ينتهي حد السرعة 50 الظاهر هنا؟","answersAr":["عند التقاطع التالي.","عند علامة تحدد سرعة أخرى.","تلقائيًا عند نهاية المنطقة المأهولة.","بعد علامة توقف إلزامي."],"answerReasonsAr":["التقاطع وحده لا يلغي حد السرعة المعلن.","يبقى الحد حتى يتغير بعلامة أخرى أو تنظيم ينهيه؛ لا تفترض تغيره من شكل الطريق.","نهاية المنطقة المأهولة وحدها لا تلغي حدًا محددًا بهذه العلامة.","علامة التوقف تلزمك بالتوقف في موضعها، لكنها لا ترفع حد السرعة بعده."],"explanation":"يبقى الحد حتى يتغير بعلامة أخرى أو تنظيم ينهيه؛ لا تفترض تغيره من شكل الطريق."},"q194":{"textAr":"أنت على طريق حدّه 70 كم/ساعة، وحافلة أنهت إنزال الركاب وتريد مغادرة الموقف. ما القاعدة؟","answersAr":["على الحافلة إعطائي الأولوية قبل دخول الطريق.","إذا أشارت الحافلة يسارًا فعلي إعطاؤها الأولوية دائمًا."],"answerReasonsAr":["قاعدة تسهيل خروج الحافلة الخاصة تسري على الطرق ذات حد 50 أو أقل. هنا على الحافلة التأكد من الدخول الآمن، وعليك أيضًا الاستعداد لأي خطر أو مشاة.","الإشارة لا تمنح الحافلة أولوية تلقائية على طريق حدّه 70؛ مع ذلك تعاون لتجنب الخطر."],"explanation":"قاعدة تسهيل خروج الحافلة الخاصة تسري على الطرق ذات حد 50 أو أقل. هنا على الحافلة التأكد من الدخول الآمن، وعليك أيضًا الاستعداد لأي خطر أو مشاة."},"q198":{"textAr":"ما أكبر خطر عند الانطلاق من حافة الطريق؟","answersAr":["الخطأ في تقدير سرعة المركبات القادمة من الخلف والمسافة إليها.","اختيار تعشيقة خاطئة وتوقف المحرك.","الاصطدام بسيارة مركونة قريبة أمامي."],"answerReasonsAr":["قد تصل المركبة أسرع مما تتوقع؛ افحص المرآة والنقطة العمياء واختر فجوة كافية قبل الدخول.","توقف المحرك خطر ممكن، لكن الخطأ في تقدير حركة خلفك قد يسبب اصطدامًا أسرع وأشد.","المساحة أمامك مهمة، لكن الخطر الرئيسي عند دخول حركة السير هو التقدير الخاطئ للقادمين من الخلف."],"explanation":"قد تصل المركبة أسرع مما تتوقع؛ افحص المرآة والنقطة العمياء واختر فجوة كافية قبل الدخول."},"q199":{"textAr":"تقترب سيارة بيضاء من يسارك على طريق مغطى بالثلج. كيف تتصرف؟","answersAr":["أعطيها الأولوية لأن ذلك واجب وفق قاعدة اليمين.","أزيد السرعة لأعبر قبلها.","أتابع دون تغيير لأنها قادمة من اليسار.","أخفض السرعة وأتأكد من قدرتها على التوقف."],"answerReasonsAr":["قاعدة اليمين لا تمنح القادم من اليسار الأولوية هنا؛ لكن السلامة قد تتطلب أن تفسح له إذا لم يستطع التوقف.","التسارع يقلل وقت الاستجابة ويزيد طاقة الاصطدام على طريق زلق.","أولويتك لا تضمن أن فرامل الآخر ستوقفه على الثلج.","اترك هامشًا لخطأ الآخر أو لانزلاقه؛ خفض السرعة يمكّنك من تفادي التصادم حتى عندما تكون لك الأولوية."],"explanation":"اترك هامشًا لخطأ الآخر أو لانزلاقه؛ خفض السرعة يمكّنك من تفادي التصادم حتى عندما تكون لك الأولوية."},"q200":{"textAr":"تقود في طابور داخل منطقة مأهولة. ما الأهم بصورة خاصة؟","answersAr":["إفساح الطريق لكل مركبة قادمة من جانب.","السماح للمركبات خلفي بتجاوزي.","ترك مسافة كافية خلف المركبة أمامي.","مراقبة المسار المجاور فقط."],"answerReasonsAr":["تسهيل المرور مفيد حيث يناسب القواعد، لكن لا يغني عن مسافة التوقف أمامك.","ليس هذا المطلوب الأساسي في طابور؛ لا تضغط نفسك بمناورات غير ضرورية.","قد يتوقف الطابور فجأة؛ المسافة تمنحك زمنًا للتصرف وتجنب الاصطدام الخلفي.","راقب جميع الجهات، لكن التركيز على المجاور لا يعوض مسافة أمان أمامية."],"explanation":"قد يتوقف الطابور فجأة؛ المسافة تمنحك زمنًا للتصرف وتجنب الاصطدام الخلفي."},"q202":{"textAr":"متى يجب إعطاء تنبيه ضوئي عند الحاجة؟","answersAr":["في كل تجاوز داخل منطقة مأهولة.","عندما يلزم لتفادي خطر في الظلام.","فقط عند تجاوز دراجتين تسيران جنبًا إلى جنب."],"answerReasonsAr":["التجاوز لا يستلزم الوميض تلقائيًا؛ استخدم التنبيه عند ضرورة السلامة.","تنبيه ضوئي قصير قد يحذر من خطر ليلي؛ تجنب الإبهار ولا تستعمله لفرض الأولوية.","الحاجة إلى التحذير لا تقتصر على الدراجات؛ قد تنشأ في مواقف أخرى."],"explanation":"تنبيه ضوئي قصير قد يحذر من خطر ليلي؛ تجنب الإبهار ولا تستعمله لفرض الأولوية."},"q208":{"textAr":"ما الخطر الأكبر في موضعك أثناء تجاوز راكب الدراجة النارية في الصورة؟","answersAr":["قد تجعله دوامة الهواء الناتجة عن سيارتي يتمايل.","سأتجاوز بالضرورة حد السرعة المسموح.","قد أكون في نقطته العمياء فيغير اتجاهه فجأة أمامي."],"answerReasonsAr":["تأثير الهواء ممكن ويستدعي مسافة جانبية، لكن الخطر الرئيسي هنا أن الراكب قد لا يراك.","التجاوز لا يستلزم مخالفة السرعة؛ لا تبدأه إذا لم يمكن إتمامه ضمن الحد.","في النقطة العمياء قد لا تظهر في مرآته؛ لا تبقَ إلى جانبه بلا داعٍ، واترك هامشًا لحركة جانبية غير متوقعة."],"explanation":"في النقطة العمياء قد لا تظهر في مرآته؛ لا تبقَ إلى جانبه بلا داعٍ، واترك هامشًا لحركة جانبية غير متوقعة."},"q210":{"textAr":"ما المقصود بالقيادة الدفاعية؟","answersAr":["التوقع ومراعاة الآخرين وتجنب تعريضهم للمخاطر.","السير ببطء دائمًا والاكتفاء باتباع القواعد حرفيًا.","إظهار الخبرة وسرعة الاستجابة في المواقف المعقدة."],"answerReasonsAr":["تخطط مبكرًا وتترك مسافة وتتوقع أخطاء الآخرين؛ تمنع الموقف الخطر قبل الحاجة إلى إنقاذه.","البطء غير المبرر قد يعرقل المرور، واتباع القاعدة دون قراءة الخطر لا يكفي.","القيادة ليست استعراضًا للمهارة؛ الوقاية أكثر أمانًا من الاعتماد على رد فعل سريع."],"explanation":"تخطط مبكرًا وتترك مسافة وتتوقع أخطاء الآخرين؛ تمنع الموقف الخطر قبل الحاجة إلى إنقاذه."},"q211":{"textAr":"هل موضع السيارة الحمراء صحيح؟","answersAr":["نعم إذا توقفت لإركاب أو إنزال أشخاص.","نعم إذا توقفت للتحميل أو التفريغ.","نعم إذا انتظر السائق خمس دقائق لإنجاز عمل.","لا؛ الركن ممنوع هنا."],"answerReasonsAr":["السيارة تشغل مسار الدراجات؛ لا تبرر خدمة الركاب إغلاقه، ويشمل المنع التوقف أيضًا.","التحميل لا يبيح سد مسار الدراجات وإجبار الراكب على الدخول أمام المركبات.","خمس دقائق تُعد ركنًا إذا كان الهدف انتظار عمل، وقصر المدة لا يلغي المنع.","السيارة تقف في مسار الدراجات فتعرقل مستخدميه؛ اختر مكانًا مسموحًا خارج المسار."],"explanation":"السيارة تقف في مسار الدراجات فتعرقل مستخدميه؛ اختر مكانًا مسموحًا خارج المسار."},"q212":{"textAr":"ماذا تعني علامة منع الركن مع السهمين؟","answersAr":["الركن ممنوع قبل العلامة وبعدها ضمن النطاق المحدد.","التوقف ممنوع قبل العلامة وبعدها.","الركن مسموح بعد العلامة فقط.","الركن مسموح قبل العلامة فقط."],"answerReasonsAr":["السهمان يوضحان استمرار نطاق منع الركن في الاتجاهين من موضع اللوحة.","الشريط الأحمر الواحد يعني منع الركن؛ منع التوقف والركن يحمل تقاطعًا أحمر. تبقى قواعد التوقف الأخرى واجبة.","السهم الصاعد لا يقف وحده؛ السهمان يعنيان أن المنع يمتد قبل وبعد.","السهم الهابط ليس نهاية منفردة هنا؛ يوجد سهمان يبيّنان امتداد المنع من الجهتين."],"explanation":"السهمان يوضحان استمرار نطاق منع الركن في الاتجاهين من موضع اللوحة."},"q214":{"textAr":"لماذا توضع علامة تحذير من إشارة ضوئية؟","answersAr":["لأستعد وأخفض السرعة مبكرًا، مما يقلل خطر اصطدام المركبات من الخلف.","لأعطي الطريق المتقاطع الأولوية دائمًا.","لأن الإشارة الضوئية متوقفة عن العمل."],"answerReasonsAr":["قد تكون الإشارة أو الطابور خلفها غير متوقَّعين؛ الإبطاء التدريجي يعطيك ويعطي من خلفك وقتًا للاستجابة.","الأولوية تحددها الإشارة عند الوصول؛ علامة التحذير لا تعني إفساحًا دائمًا للطريق الآخر.","العلامة تنبه إلى وجود إشارة، ولا تعني أنها معطلة."],"explanation":"قد تكون الإشارة أو الطابور خلفها غير متوقَّعين؛ الإبطاء التدريجي يعطيك ويعطي من خلفك وقتًا للاستجابة."},"q215":{"textAr":"ما الذي قد يجعل المرور أصعب لكبار السن؟","answersAr":["أنهم لا يفهمون حركة المرور الحديثة.","أنهم غالبًا لا يحملون رخص قيادة.","أنهم قد يحتاجون إلى وقت أطول للمشي وعبور الطريق."],"answerReasonsAr":["هذا تعميم غير صحيح؛ لا تُقيّم قدرة الشخص على الفهم من عمره وحده.","امتلاك الرخصة ليس العامل المقصود بصعوبة عبور الطريق كمشاة.","قد تقل سرعة المشي والتوازن، فيحتاج الشخص وقتًا ومسافة أكبر؛ انتظر دون استعجاله."],"explanation":"قد تقل سرعة المشي والتوازن، فيحتاج الشخص وقتًا ومسافة أكبر؛ انتظر دون استعجاله."},"q216":{"textAr":"متى ينتهي منع التجاوز الذي تفرضه هذه العلامة؟","answersAr":["عند التقاطع التالي تلقائيًا.","بعد مسافة تتراوح بين 150 و250 مترًا.","عند علامة انتهاء المنع، ما لم يحدد امتداده بطريقة أخرى."],"answerReasonsAr":["التقاطع وحده لا ينهي منع التجاوز المفروض بهذه العلامة.","لا توجد مسافة انتهاء ثابتة كهذه؛ قد تبين لوحة إضافية طول المنطقة.","تابع المنع حتى علامة نهايته أو نهاية الامتداد المبين؛ ثم تحقق من جواز التجاوز وفق بقية القواعد أيضًا."],"explanation":"تابع المنع حتى علامة نهايته أو نهاية الامتداد المبين؛ ثم تحقق من جواز التجاوز وفق بقية القواعد أيضًا."},"q217":{"textAr":"تريد تغيير اتجاهك على شارع مزدحم في المدينة. ما الطريقة الأنسب؟","answersAr":["أقوم بدوران سريع للرجوع.","أرجع للخلف إلى شارع جانبي.","أدور حول مربع المباني عبر الشوارع المسموحة."],"answerReasonsAr":["سرعة المناورة لا تجعلها آمنة؛ الدوران قد يقطع عدة مسارات ويعرقل المرور.","الرجوع عند تقاطع مزدحم يزيد صعوبة رؤية المشاة والمركبات.","الدوران عبر شوارع مناسبة يغيّر اتجاهك دون رجوع أو مناورة حادة وسط الحركة؛ راعِ الاتجاهات والقيود."],"explanation":"الدوران عبر شوارع مناسبة يغيّر اتجاهك دون رجوع أو مناورة حادة وسط الحركة؛ راعِ الاتجاهات والقيود."},"q218":{"textAr":"في أي صورة يأمرك الشرطي بخفض السرعة؟","answersAr":["الصورة A.","الصورة B.","الصورة C."],"answerReasonsAr":["الذراع الممدودة دون حركة الخفض ليست إشارة تقليل السرعة المعروضة في B؛ انتبه إلى وضع الشرطي ومعنى التوقف.","حركة الذراع صعودًا وهبوطًا تطلب خفض السرعة؛ استجب تدريجيًا وراقب أي تعليمات تالية.","حركة الذراع في C تدعو المرور للتقدم في الاتجاه المقصود؛ ليست حركة خفض السرعة الرأسية."],"explanation":"حركة الذراع صعودًا وهبوطًا تطلب خفض السرعة؛ استجب تدريجيًا وراقب أي تعليمات تالية."},"q219":{"textAr":"ما واجبك تجاه المشاة عند الممر الذي تحمل جهته علامة عبور لكن خطوطه الأرضية غير ظاهرة؟","answersAr":["أفسح للمشاة رغم غياب الخطوط الأرضية.","لا يلزمني الانتظار لعدم وجود الخطوط."],"answerReasonsAr":["يمكن تعريف ممر المشاة بالعلامة أو العلامة الأرضية؛ اختفاء الخطوط لا يلغي واجب إعطاء الأولوية عند هذا الممر غير المنظّم.","لا تعتمد على الطلاء وحده؛ علامة الممر قائمة والشخص يريد العبور."],"explanation":"يمكن تعريف ممر المشاة بالعلامة أو العلامة الأرضية؛ اختفاء الخطوط لا يلغي واجب إعطاء الأولوية عند هذا الممر غير المنظّم."},"q220":{"textAr":"أي صورتين تُظهران موضعًا قد يكون عبور خط الوسط فيه شديد الخطورة؟","answersAr":["2 و3.","1 و2.","2 و4.","1 و4."],"answerReasonsAr":["في 2 قرب القمة وفي 3 عند المنعطف الرؤية محدودة وخط التحذير أطول؛ قد تكون مركبة مقابلة مخفية.","2 خطرة، لكن 1 ليست الحالة الثانية المحدودة الرؤية المقصودة؛ الصورة 3 هي الأخرى.","2 صحيحة، لكن 4 ليست موضع الخطر الثاني في المقارنة؛ راقب المنعطف في 3.","1 و4 لا تمثلان موضعي التحذير المقصودين. الخط المتقطع لا يعني أن العبور آمن تلقائيًا في أي صورة."],"explanation":"في 2 قرب القمة وفي 3 عند المنعطف الرؤية محدودة وخط التحذير أطول؛ قد تكون مركبة مقابلة مخفية."},"q221":{"textAr":"أي علامة تُلزمك بالسير مستقيمًا في التقاطع التالي؟","answersAr":["العلامة A.","العلامة B.","العلامة C.","العلامة D."],"answerReasonsAr":["الدائرة الزرقاء بسهم مستقيم هي إلزام بهذا الاتجاه.","منع اليسار لا يمنع اليمين، فلا يعني الاستقامة وحدها.","المثلث يحذر من مرور في الاتجاهين، ولا يفرض الاستقامة.","السهمان يسمحان بالاستقامة أو اليمين، فلا يلزمانك بالاستقامة وحدها."],"explanation":"الدائرة الزرقاء بسهم مستقيم هي إلزام بهذا الاتجاه."},"q222":{"textAr":"ماذا تعني هذه العلامة عند جزء ضيق لا يسمح بتقابل مركبتين؟","answersAr":["على المرور المقابل إفساح الطريق لي.","علي إعطاء الأولوية للمقابل.","من يصل أولًا يمر أولًا دائمًا."],"answerReasonsAr":["السهم الأبيض في اتجاهك يمنحك الأولوية على المقابل عند التضيق؛ مع ذلك لا تدخل إذا كانت مركبة داخله ولا يمكنها الخروج بأمان.","علامة إعطاء الأولوية للمقابل مختلفة ودائرية؛ اللوحة الزرقاء هنا تعطيك الأولوية.","العلامة تحدد الأولوية، لا سباق الوصول؛ تجنب إجبار مركبة موجودة في الممر على مناورة خطرة."],"explanation":"السهم الأبيض في اتجاهك يمنحك الأولوية على المقابل عند التضيق؛ مع ذلك لا تدخل إذا كانت مركبة داخله ولا يمكنها الخروج بأمان."},"q225":{"textAr":"تركن الأربعاء 27 مايو الساعة 19:00 وتغادر الخميس الساعة 09:00. أي جانب تختار وفق لوحة منع الركن حسب التاريخ من 00:00 إلى 06:00؟","answersAr":["لا يجوز أي جانب.","جانب أرقام المنازل الفردية.","جانب أرقام المنازل الزوجية."],"answerReasonsAr":["وقت الوصول 19:00 خارج ساعات المنع؛ يوجد جانب مناسب لفترة الليل.","خلال فترة المنع بعد منتصف الليل يصبح التاريخ 28، وهو زوجي؛ يُمنع الجانب الزوجي وتختار الفردي. احسب تاريخ ساعات المنع لا تاريخ الوصول فقط.","الجانب الزوجي سيُمنع من 00:00 إلى 06:00 يوم 28؛ لا يصلح للبقاء طوال الفترة المذكورة."],"explanation":"خلال فترة المنع بعد منتصف الليل يصبح التاريخ 28، وهو زوجي؛ يُمنع الجانب الزوجي وتختار الفردي. احسب تاريخ ساعات المنع لا تاريخ الوصول فقط."},"q226":{"textAr":"ماذا تفعل أمام النفق في هذه الحالة؟","answersAr":["أتوقف لأن الإشارة الضوئية حمراء.","أتابع لأن العلامة تعطي المرور في اتجاهي الأولوية على المقابل."],"answerReasonsAr":["الإشارة الحمراء تتحكم بالمرور الآن وتتقدم على أولوية التضيق؛ انتظر السماح.","علامة الأولوية عند التضيق لا تبيح تجاوز ضوء أحمر."],"explanation":"الإشارة الحمراء تتحكم بالمرور الآن وتتقدم على أولوية التضيق؛ انتظر السماح."},"q227":{"textAr":"إذا اجتمعت تعليمات متعارضة عند التقاطع، أيها تتبع أولًا؟","answersAr":["الإشارة الضوئية.","قاعدة اليمين.","علامة إعطاء الأولوية.","إشارة الشرطي."],"answerReasonsAr":["الإشارة الضوئية تأتي بعد تعليمات الشرطي عند التعارض.","القواعد العامة تطبق عند غياب تعليمات تتقدم عليها.","علامة الأولوية لا تتقدم على أمر الشرطي الذي ينظم الموقف.","اتبع الشرطي حتى إذا خالفت تعليماته الضوء أو العلامة؛ راقب بدقة من يوجه الإشارة إليه."],"explanation":"اتبع الشرطي حتى إذا خالفت تعليماته الضوء أو العلامة؛ راقب بدقة من يوجه الإشارة إليه."},"q229":{"textAr":"من يجوز له الركن في هذه المواقف المخصصة؟","answersAr":["مستخدمو الكراسي المتحركة فقط.","ذوو الإعاقة الحركية الحاصلون على تصريح الركن الخاص.","أي سائق ينقل راكبًا مسنًا لديه صعوبة في الحركة."],"answerReasonsAr":["الكرسي المتحرك ليس بديلًا عن التصريح، كما قد يُمنح التصريح لمن لا يستخدم كرسيًا.","يلزم تصريح صالح واستخدامه وفق شروطه؛ الموقف مخصص لحامل التصريح.","وجود راكب مسن أو ذي إعاقة لا يمنح الحق تلقائيًا دون التصريح المطلوب."],"explanation":"يلزم تصريح صالح واستخدامه وفق شروطه؛ الموقف مخصص لحامل التصريح."},"q230":{"textAr":"أنت في شارع باتجاه واحد وتريد الانعطاف يسارًا. أين تتموضع؟","answersAr":["أقرب ما يمكن إلى اليمين.","أقرب ما يمكن إلى اليسار بصورة آمنة.","في منتصف الشارع."],"answerReasonsAr":["اليمين موضع الانعطاف اليميني عادةً، وليس اليساري هنا.","في شارع باتجاه واحد اقترب من اليسار قبل الانعطاف ما لم تحدد العلامات غير ذلك؛ أشر وافحص الدراجات إلى جانبك.","الوسط قد يترك فراغًا ملتبسًا ويعرقل الآخرين؛ الموضع الأيسر يوضح نية الانعطاف."],"explanation":"في شارع باتجاه واحد اقترب من اليسار قبل الانعطاف ما لم تحدد العلامات غير ذلك؛ أشر وافحص الدراجات إلى جانبك."},"q231":{"textAr":"ما القاعدة داخل منطقة السير بسرعة المشي؟","answersAr":["يجب على المركبات إعطاء المشاة الأولوية.","مرور المركبات عبر المنطقة ممنوع دائمًا.","جميع المركبات ذات المحرك ممنوعة.","السرعة القصوى الموصى بها 30 كم/ساعة."],"answerReasonsAr":["تحرك بسرعة المشي وأفسح للمشاة؛ المنطقة مصممة لتشارك الطريق مع أولوية المشاة.","هذا ليس منع عبور تلقائيًا؛ لا تخلط المنطقة بشارع المشاة أو قيود أخرى قد تُضاف.","المركبات قد تدخل وفق التنظيم، لكن بسرعة المشي ومع إعطاء المشاة الأولوية.","السرعة هنا سرعة المشي وليست توصية بـ30؛ هذا حد سلوكي أقل بكثير."],"explanation":"تحرك بسرعة المشي وأفسح للمشاة؛ المنطقة مصممة لتشارك الطريق مع أولوية المشاة."},"q232":{"textAr":"هل يجب أن تعطي هذا المشاة الأولوية في الحالة الظاهرة؟","answersAr":["نعم.","لا."],"answerReasonsAr":["الصورة تُظهر ضوءًا أحمر للمشاة وضوء سماح للمركبات؛ لا يملك المشاة أولوية العبور هنا لمجرد وقوفه عند الممر.","مع تنظيم الإشارات الظاهر لا توجد أولوية عبور له الآن؛ لكن إذا دخل الطريق أو بدا غير منتبه فخفف أو توقف لتجنب إصابته."],"explanation":"مع تنظيم الإشارات الظاهر لا توجد أولوية عبور له الآن؛ لكن إذا دخل الطريق أو بدا غير منتبه فخفف أو توقف لتجنب إصابته."},"q085":{"textAr":"ماذا تعني هذه العلامة؟","answersAr":["توجيه المركبات التي تحمل مواد خطرة.","تحويل مؤقت لحركة المرور.","اتجاه شارع أحادي الاتجاه."],"answerReasonsAr":["نقل المواد الخطرة له رموز خاصة؛ لا يدل هذا السهم وحده عليه.","السهم البرتقالي يحدد اتجاه تحويلة مؤقتة؛ اتبع بقية علامات التحويل.","الاتجاه الواحد يُبيّن بعلامة زرقاء وسهم أبيض، لا بهذا السهم البرتقالي."],"explanation":"السهم البرتقالي يحدد اتجاه تحويلة مؤقتة؛ اتبع بقية علامات التحويل."},"q089":{"textAr":"ما الفرق البنيوي بين الطريق السريع والطريق المخصص لحركة المركبات؟","answersAr":["سرعة الطريق السريع دائمًا 110 كم/ساعة.","سرعة الطريق المخصص للمركبات دائمًا 90 كم/ساعة.","الطريق السريع يتكون من قسمين منفصلين للسير، أحدهما لكل اتجاه."],"answerReasonsAr":["قد تختلف سرعة الطريق السريع حسب الموقع والعلامات؛ ليست دائمًا 110.","قد تختلف السرعة المقررة للطريق المخصص للمركبات؛ ليست دائمًا 90.","الفصل بين الاتجاهين من خصائص الطريق السريع، بينما لا يشترط الفصل نفسه في الطريق المخصص للمركبات. قد توجد تحويلات مؤقتة أثناء الأعمال."],"explanation":"الفصل بين الاتجاهين من خصائص الطريق السريع، بينما لا يشترط الفصل نفسه في الطريق المخصص للمركبات. قد توجد تحويلات مؤقتة أثناء الأعمال."},"q096":{"textAr":"متى يُستخدم التحذير الرباعي بصورة صحيحة؟","answersAr":["عند عطل في المحرك يجعل المركبة خطرًا على الآخرين.","لتحميل أو تفريغ أغراض ضمن عشرة أمتار من تقاطع.","لإنزال أو إركاب شخص بعد قمة تحجب الرؤية.","للركن أمام مدخل عقار."],"answerReasonsAr":["يشير إلى خطر غير معتاد كالتعطل في الطريق؛ حاول تأمين موضع المركبة والأشخاص أيضًا.","الأضواء لا تلغي منع التوقف قرب التقاطع ولا تبيح التحميل فيه.","التوقف في موضع محدود الرؤية خطر؛ التحذير لا يجعله مناسبًا لإنزال الركاب اختيارًا.","إعاقة المدخل لا تصبح مشروعة بتشغيل التحذير."],"explanation":"يشير إلى خطر غير معتاد كالتعطل في الطريق؛ حاول تأمين موضع المركبة والأشخاص أيضًا."},"q102":{"textAr":"لمن يجب تقديم رخصة القيادة للفحص عند طلبها أثناء الرقابة المرورية؟","answersAr":["موظف في جهة الإنقاذ.","موظف في إدارة المحافظة.","مفتش مركبات تابع للشرطة.","موظف في شركة الفحص الدوري."],"answerReasonsAr":["مجرد العمل في الإنقاذ لا يمنح صلاحية طلب الرخصة لهذا الغرض الرقابي.","هذه ليست الجهة المخوّلة هنا بإيقافك لفحص الرخصة أثناء السير.","يجب تقديمها لشرطي أو مفتش مركبات مخوّل عند طلبها؛ الخيار المذكور من هذه الفئة.","قد تطلب شركة الفحص بيانات لإتمام خدمتها، لكنها ليست جهة الرقابة المرورية المقصودة في السؤال."],"explanation":"يجب تقديمها لشرطي أو مفتش مركبات مخوّل عند طلبها؛ الخيار المذكور من هذه الفئة."},"q203":{"textAr":"لمن يجب تقديم رخصة القيادة للفحص عند طلبها أثناء الرقابة المرورية؟","answersAr":["موظف في جهة الإنقاذ.","موظف في إدارة المحافظة.","مفتش مركبات تابع للشرطة.","موظف في شركة الفحص الدوري."],"answerReasonsAr":["مجرد العمل في الإنقاذ لا يمنح صلاحية طلب الرخصة لهذا الغرض الرقابي.","هذه ليست الجهة المخوّلة هنا بإيقافك لفحص الرخصة أثناء السير.","يجب تقديمها لشرطي أو مفتش مركبات مخوّل عند طلبها؛ الخيار المذكور من هذه الفئة.","قد تطلب شركة الفحص بيانات لإتمام خدمتها، لكنها ليست جهة الرقابة المرورية المقصودة في السؤال."],"explanation":"يجب تقديمها لشرطي أو مفتش مركبات مخوّل عند طلبها؛ الخيار المذكور من هذه الفئة."},"q104":{"textAr":"توقفت خلف مركبة عند تقاطع فيه توقف إلزامي. هل يجوز دخول التقاطع معها دون توقف جديد عند موضع التوقف؟","answersAr":["نعم.","نعم إذا كانت الرؤية واضحة.","لا؛ يجب أن أتوقف أنا أيضًا عند موضع التوقف المقرر."],"answerReasonsAr":["توقف المركبة أمامك لا يفي بالتزامك الشخصي عند خط التوقف.","وضوح الرؤية لا يلغي علامة STOP؛ يلزم توقف كامل.","تقدم حتى خط التوقف وتوقف، أو قبل الطريق المتقاطع عند غياب الخط؛ الوقوف بعيدًا خلف سيارة لا يعوض هذا التوقف."],"explanation":"تقدم حتى خط التوقف وتوقف، أو قبل الطريق المتقاطع عند غياب الخط؛ الوقوف بعيدًا خلف سيارة لا يعوض هذا التوقف."},"q106":{"textAr":"تسببت في حادث دون إصابات، ولم تتضرر سيارتك. أي واجب ينطبق؟","answersAr":["أقدم اسمي وعنواني للأطراف الأخرى المعنية عند الطلب.","يجب إبلاغ الشرطة بكل حادث كهذا.","يجب قانونًا إبلاغ شركة التأمين بكل حادث كهذا."],"answerReasonsAr":["عدم تضرر سيارتك لا يلغي واجب التوقف وتبادل بيانات التعريف مع المتضررين.","لا يستدعي كل ضرر مادي بسيط إبلاغ الشرطة؛ تختلف الحال عند إصابة أو ظروف خاصة.","قد يتطلب عقد التأمين أو طلب التعويض إخطار الشركة، لكن الواجب المروري المباشر الذي يختبره السؤال هو تقديم البيانات للأطراف المعنية."],"explanation":"عدم تضرر سيارتك لا يلغي واجب التوقف وتبادل بيانات التعريف مع المتضررين."},"q147":{"textAr":"تسببت في حادث دون إصابات، ولم تتضرر سيارتك. أي واجب ينطبق؟","answersAr":["أقدم اسمي وعنواني للأطراف الأخرى المعنية عند الطلب.","يجب إبلاغ الشرطة بكل حادث كهذا.","يجب قانونًا إبلاغ شركة التأمين بكل حادث كهذا."],"answerReasonsAr":["عدم تضرر سيارتك لا يلغي واجب التوقف وتبادل بيانات التعريف مع المتضررين.","لا يستدعي كل ضرر مادي بسيط إبلاغ الشرطة؛ تختلف الحال عند إصابة أو ظروف خاصة.","قد يتطلب عقد التأمين أو طلب التعويض إخطار الشركة، لكن الواجب المروري المباشر الذي يختبره السؤال هو تقديم البيانات للأطراف المعنية."],"explanation":"عدم تضرر سيارتك لا يلغي واجب التوقف وتبادل بيانات التعريف مع المتضررين."},"q111":{"textAr":"أشرت لتغيير المسار في حركة مزدحمة. ما الصحيح؟","answersAr":["على السائقين الآخرين إفساح المكان لي حتمًا.","عليّ التأكد من إمكان تغيير المسار دون خطر.","يمكنني التأكد من أن الآخرين سيسمحون لي بالدخول."],"answerReasonsAr":["الإشارة تعلن نيتك ولا تمنحك أولوية الدخول؛ تعاون الآخرين لا يغني عن تحققك.","افحص المرايا والنقطة العمياء وانتظر فجوة مناسبة؛ لا تبدأ انتقالًا يفرض كبحًا خطرًا على غيرك.","لا تفترض أن الآخر رآك أو سيتعاون؛ يجب التأكد قبل التحرك."],"explanation":"افحص المرايا والنقطة العمياء وانتظر فجوة مناسبة؛ لا تبدأ انتقالًا يفرض كبحًا خطرًا على غيرك."},"q112":{"textAr":"أي لوحة يجب أن تكون على يمين مركبتك عند المرور بجانبها؟","answersAr":["اللوحة A.","اللوحة B."],"answerReasonsAr":["الخطوط في A تميل نحو الأسفل إلى اليسار، أي جهة المرور الآمنة يسار اللوحة؛ لذا تبقى اللوحة على يمينك.","في B تميل الخطوط إلى أسفل اليمين، فتوجهك إلى المرور من يمينها وتبقى اللوحة على يسارك."],"explanation":"الخطوط في A تميل نحو الأسفل إلى اليسار، أي جهة المرور الآمنة يسار اللوحة؛ لذا تبقى اللوحة على يمينك."},"q116":{"textAr":"أي عبارة صحيحة وفق العلامات الظاهرة؟","answersAr":["يوجد معبر سكة دون حواجز بعد نحو 100 متر.","يجوز الركن على بعد 20 مترًا بعد معبر السكة.","يوجد معبر سكة بحواجز بعد 100 متر.","علامة التقاطع المتصالب تدل على عدة مسارات للقطارات."],"answerReasonsAr":["صورة القاطرة تحذر من معبر دون حواجز، ولوحة 100 م تحدد المسافة إليه.","يُمنع الركن ضمن 30 مترًا من معبر السكة؛ 20 مترًا لا تكفي.","المعبر المزود بحواجز له رمز حاجز؛ الرمز هنا قاطرة.","الصليب الواحد يدل على مسار سكة واحد؛ تعدد المسارات يُبيّن بجزء إضافي أسفل الصليب."],"explanation":"صورة القاطرة تحذر من معبر دون حواجز، ولوحة 100 م تحدد المسافة إليه."},"q117":{"textAr":"كيف يتصرف سائق قادر على ضبط نفسه؟","answersAr":["يغير المسارات باستمرار ليتقدم بسهولة.","يسبق من يريد الانتقال إلى مساره ويمنعه من الدخول.","يصر على حقه في المرور مهما كانت الظروف.","يراعي الآخرين حتى من يتصرفون وكأنهم أفضل منه."],"answerReasonsAr":["كثرة الانتقال غير الضروري تزيد التعارض والمخاطر، ولا تثبت التحكم بالنفس.","منع الآخر بدافع المنافسة قد يسبب حادثًا؛ افسح عند الحاجة بأمان.","الأولوية لا تبرر الاصطدام؛ ضبط النفس يعني تجنب التصعيد.","يبقى هادئًا ويختار السلامة بدل الرد على الاستفزاز، ويساعد على تصحيح الموقف."],"explanation":"يبقى هادئًا ويختار السلامة بدل الرد على الاستفزاز، ويساعد على تصحيح الموقف."},"q118":{"textAr":"أي عبارة صحيحة عن توجيه النظر أثناء القيادة؟","answersAr":["النظر قريبًا جدًا أمام السيارة يجعل الحفاظ على المسار أكثر ثباتًا.","تثبيت النظر على جسم واحد قد يجعلني أغفل المعلومات المحيطة به.","السائق المبتدئ ينظر عادةً إلى مسافة أبعد من السائق الخبير."],"answerReasonsAr":["النظر بعيدًا بما يناسب الطريق يساعد على سلاسة التوجيه؛ التحديق قرب مقدمة السيارة يضيّق الاستعداد.","عندما تركز على نقطة واحدة قد تفوتك مركبة أو مشاة بجوارها؛ حرّك النظر بين البعيد والقريب والمرايا.","المبتدئ يميل إلى النظر قريبًا أكثر، بينما يستخدم الخبير مراقبة أوسع وأبعد."],"explanation":"عندما تركز على نقطة واحدة قد تفوتك مركبة أو مشاة بجوارها؛ حرّك النظر بين البعيد والقريب والمرايا."},"q207":{"textAr":"أي عبارة صحيحة عن توجيه النظر أثناء القيادة؟","answersAr":["النظر قريبًا جدًا أمام السيارة يجعل الحفاظ على المسار أكثر ثباتًا.","تثبيت النظر على جسم واحد قد يجعلني أغفل المعلومات المحيطة به.","السائق المبتدئ ينظر عادةً إلى مسافة أبعد من السائق الخبير."],"answerReasonsAr":["النظر بعيدًا بما يناسب الطريق يساعد على سلاسة التوجيه؛ التحديق قرب مقدمة السيارة يضيّق الاستعداد.","عندما تركز على نقطة واحدة قد تفوتك مركبة أو مشاة بجوارها؛ حرّك النظر بين البعيد والقريب والمرايا.","المبتدئ يميل إلى النظر قريبًا أكثر، بينما يستخدم الخبير مراقبة أوسع وأبعد."],"explanation":"عندما تركز على نقطة واحدة قد تفوتك مركبة أو مشاة بجوارها؛ حرّك النظر بين البعيد والقريب والمرايا."},"q119":{"textAr":"ما المقصود بقاعدة الثواني الثلاث؟","answersAr":["طريقة لتقدير مسافة تتابع مناسبة خلف المركبة الأمامية.","طريقة لحساب مسافة الكبح بدقة.","طريقة لتحديد متى أشغّل إشارة الانعطاف قبل التقاطع.","طريقة لقياس المسافة إلى المركبة خلفي."],"answerReasonsAr":["اختر معلمًا تمر به المركبة الأمامية، ويُفترض أن تمر به بعد ثلاث ثوانٍ على الأقل في ظروف مناسبة. زد الفاصل مع المطر والجليد وضعف الرؤية؛ ليست ضمانًا لكل الظروف.","مسافة الكبح تعتمد على السرعة والتماسك والفرامل؛ القاعدة تقيس فاصل التتابع الزمني.","توقيت الإشارة يعتمد على الموقف ووضوح النية، وليس قاعدة الثواني الثلاث هذه.","تقيس الفاصل إلى من أمامك؛ لا يمكنك التحكم المباشر في مسافة من خلفك."],"explanation":"اختر معلمًا تمر به المركبة الأمامية، ويُفترض أن تمر به بعد ثلاث ثوانٍ على الأقل في ظروف مناسبة. زد الفاصل مع المطر والجليد وضعف الرؤية؛ ليست ضمانًا لكل الظروف."},"q123":{"textAr":"ماذا تعني لوحة 400 م أسفل التحذير؟","answersAr":["المسافة من العلامة إلى بداية موضع الخطر.","المسافة إلى نهاية الخطر.","أقل مسافة يجب تركها خلف السيارة الأمامية فوق الجسر."],"answerReasonsAr":["ستصل إلى الجسر المتحرك بعد 400 متر؛ استعمل المسافة للاستعداد ومراقبة الإشارات والحواجز.","الرقم دون بيان امتداد لا يحدد نهاية الخطر، بل المسافة إلى بدايته.","هذه لوحة مسافة إلى الخطر؛ تحديد فاصل المركبات له علامة مختلفة."],"explanation":"ستصل إلى الجسر المتحرك بعد 400 متر؛ استعمل المسافة للاستعداد ومراقبة الإشارات والحواجز."},"q126":{"textAr":"أي تصرف يدل على عدم النضج في المرور؟","answersAr":["أرفض السماح لسائق بالدخول إلى مساري بدافع العناد.","أتسارع بقوة مناسبة على مدخل الطريق السريع.","أستخدم كتفًا صالحًا ومسموحًا به لتسهيل التجاوز."],"answerReasonsAr":["رفض التعاون لمجرد التمسك بالموقع يزيد الاحتكاك والخطر؛ لا يعني ذلك وجوب قبول انتقال غير آمن.","التسارع المناسب قد يلزم لمواءمة سرعة المرور قبل الاندماج؛ ليس تهورًا بحد ذاته.","تسهيل المرور قد يكون تعاونًا صحيحًا إذا سمحت القواعد وكان الكتف آمنًا وخاليًا؛ لا تفعله تلقائيًا."],"explanation":"رفض التعاون لمجرد التمسك بالموقع يزيد الاحتكاك والخطر؛ لا يعني ذلك وجوب قبول انتقال غير آمن."},"q129":{"textAr":"تقود ببطء على طريق مزدحم وتشكل خلفك طابور. ماذا ينبغي أن تفعل؟","answersAr":["أبقى في موضعي وأخفف السرعة أكثر.","أشغّل إشارة اليمين لأخبر الآخرين أن التجاوز آمن.","أدخل أقرب جيب توقف مناسب وأسمح للطابور بالمرور."],"answerReasonsAr":["إبطاء الحركة أكثر دون سبب يزيد العرقلة بدل حلها.","الإشارة تستخدم لبيان نيتك، لا لضمان سلامة تجاوز غيرك؛ كل سائق يقيّم التجاوز بنفسه.","اختر موضعًا يسمح بالخروج والعودة بأمان؛ تفسح الطريق دون الضغط على نفسك لسرعة غير آمنة."],"explanation":"اختر موضعًا يسمح بالخروج والعودة بأمان؛ تفسح الطريق دون الضغط على نفسك لسرعة غير آمنة."},"q130":{"textAr":"أي عبارة تصف الاتجاه العام في حوادث السائقين الشباب؟","answersAr":["معدل حوادث الشبان والشابات متطابق عند مراعاة المسافة المقطوعة.","الشابات يتورطن في حوادث أكثر من الشبان.","الشبان يتورطون في حوادث أكثر من الشابات."],"answerReasonsAr":["الفروق الإحصائية لا تختفي بالضرورة عند مراعاة المسافة؛ نوع القيادة والمخاطرة مهمان أيضًا.","هذا ليس الاتجاه العام المقصود؛ المخاطرة والحوادث الشديدة أعلى لدى الشبان في الإحصاءات العامة.","هذه مقارنة على مستوى المجموعات، وليست حكمًا على كل شخص. التهور والسرعة والكحول عوامل يمكن لكل سائق تجنبها بغض النظر عن جنسه."],"explanation":"هذه مقارنة على مستوى المجموعات، وليست حكمًا على كل شخص. التهور والسرعة والكحول عوامل يمكن لكل سائق تجنبها بغض النظر عن جنسه."},"q136":{"textAr":"كيف تُظهر سلوكًا جيدًا في المرور؟","answersAr":["أقبل تحديات الآخرين بسهولة.","أتمسك بأولويتي مهما حدث.","أساعد على تفادي عواقب أخطاء الآخرين.","أتنقل باستمرار بين المسارات للتقدم بسرعة."],"answerReasonsAr":["قبول التحدي يحول القيادة إلى منافسة وقد يرفع السرعة والمجازفة.","أولوية المرور لا تعفيك من تجنب حادث يمكن منعه.","خفف السرعة أو افتح فجوة آمنة إذا أخطأ غيرك؛ الهدف إنهاء الموقف بسلام.","التنقل المتكرر يزيد نقاط التعارض؛ خطط لمسارك مبكرًا."],"explanation":"خفف السرعة أو افتح فجوة آمنة إذا أخطأ غيرك؛ الهدف إنهاء الموقف بسلام."},"q139":{"textAr":"في أي حالة من الآتي يجب استخدام إشارة الاتجاه؟","answersAr":["عند الانطلاق من حافة الطريق.","عند التوقف عند الحافة.","عند الرجوع حول زاوية شارع.","عندما يريد من خلفي تجاوزًا غير مناسب."],"answerReasonsAr":["أعلن نيتك عند الانطلاق من الحافة، ثم تحقق من المرايا والنقطة العمياء؛ الإشارة لا تمنحك الأولوية.","مجرد التوقف يُنبه إليه الكبح؛ إذا انتقلت جانبيًا إلى الحافة فعليك الإشارة أيضًا. السؤال يميز التوقف نفسه عن تغيير الموضع.","الرجوع يتطلب التأكد من السلامة؛ الإشارة ليست بديلًا عن مراقبة ما خلف المركبة.","لا تستخدم الغماز لإصدار تعليمات للمتجاوز؛ استمر بوضوح وسهّل تجنب الخطر."],"explanation":"أعلن نيتك عند الانطلاق من الحافة، ثم تحقق من المرايا والنقطة العمياء؛ الإشارة لا تمنحك الأولوية."},"q141":{"textAr":"متى يجوز تشغيل أضواء التحذير الرباعية؟","answersAr":["عند السير بحمولة بارزة أمام السيارة.","عند الوقوف في موقف حافلة لإنجاز عمل سريع.","عند إنزال راكب على طريق مزدحم.","عند تعطل المحرك على طريق ريفي وتحول السيارة إلى عائق."],"answerReasonsAr":["الحمولة البارزة لها تعليم خاص؛ التحذير الرباعي ليس بديلًا عنه.","العمل السريع لا يبرر إشغال موقف الحافلة أو يجعل المخالفة مباحة.","التوقف العادي لإنزال راكب يجب أن يكون في مكان مسموح وآمن؛ ليس مبررًا تلقائيًا للتحذير.","التحذير ينبه الآخرين إلى توقف اضطراري خطر؛ حاول تأمين المكان وإبعاد الأشخاص عن السير."],"explanation":"التحذير ينبه الآخرين إلى توقف اضطراري خطر؛ حاول تأمين المكان وإبعاد الأشخاص عن السير."},"q146":{"textAr":"ماذا تدل عليه علامة تقاطع السكة هذه؟","answersAr":["المعبر فيه مسار سكة واحد.","المعبر فيه عدة مسارات للقطارات."],"answerReasonsAr":["الصليب المفرد يدل على مسار واحد؛ تحقق مع ذلك من إشارات القطار ومن خلو العبور.","علامة المسارات المتعددة تتضمن جزءًا إضافيًا تحت الصليب؛ ليس ظاهرًا هنا."],"explanation":"الصليب المفرد يدل على مسار واحد؛ تحقق مع ذلك من إشارات القطار ومن خلو العبور."},"q151":{"textAr":"كيف تمر بالمشاة على هذا الطريق الضيق مع قدوم سيارة مقابلة؟","answersAr":["أطلق المنبّه ليبتعد المشاة عن الطريق.","أمر بالمشاة والسيارة المقابلة في اللحظة نفسها بسرعة منخفضة.","أومض بالمصابيح لأطلب من المقابل الانتظار.","أخفض السرعة وأدع السيارة المقابلة تمر أولًا، ثم أمر بالمشاة بمسافة جانبية آمنة."],"answerReasonsAr":["المنبّه لا يخلق مساحة آمنة ولا يمنحك أولوية على المشاة.","الجمع بين تقابل المركبتين ومرور المشاة في موضع ضيق يقلل الهامش الجانبي حتى مع بطء السرعة.","لا تعتمد على فهم الآخر للوميض أو انتظاره؛ يمكنك إزالة التعارض بتوقيت وصولك.","افصل بين الموقفين: انتظر التقابل ثم تجاوز المشاة بمسافة كافية دون مزاحمتهم."],"explanation":"افصل بين الموقفين: انتظر التقابل ثم تجاوز المشاة بمسافة كافية دون مزاحمتهم."},"q152":{"textAr":"لماذا يحتاج السائق إلى قدر من النضج الشخصي؟","answersAr":["ليستعيد مهارة القيادة سريعًا بعد انقطاع.","ليقيّم قدراته وحدوده كسائق تقييمًا صحيحًا.","ليستجيب منعكسيًا بصورة صحيحة في كل طارئ."],"answerReasonsAr":["استعادة المهارة تتعلق بالممارسة؛ ليست الفائدة الأساسية للنضج في السؤال.","النضج يساعدك على تجنب الثقة الزائدة ومعرفة متى تخفف السرعة أو تتراجع عن مناورة.","النضج لا يضمن رد فعل آليًا مثاليًا؛ ميزته الأساسية التقدير المسؤول قبل الخطر."],"explanation":"النضج يساعدك على تجنب الثقة الزائدة ومعرفة متى تخفف السرعة أو تتراجع عن مناورة."},"q153":{"textAr":"تريد الانعطاف يسارًا والسيارة الحمراء المقابلة ستتابع مستقيمة. من يمر أولًا؟","answersAr":["السيارة الحمراء.","أنا."],"answerReasonsAr":["انعطافك يقطع خط سير المركبة المقابلة؛ أعطها الأولوية قبل إكمال اليسار.","إشارة اليسار أو وصولك إلى التقاطع لا يمنحانك حق قطع مسار المقابل."],"explanation":"انعطافك يقطع خط سير المركبة المقابلة؛ أعطها الأولوية قبل إكمال اليسار."},"q154":{"textAr":"هل يجوز الركن بعد علامة منطقة السير بسرعة المشي؟","answersAr":["نعم وفق قاعدة التاريخ فقط.","نعم، في أماكن الركن المخصصة فقط.","نعم في أي موضع لا يعيق الآخرين.","لا، الركن ممنوع دائمًا دون استثناء."],"answerReasonsAr":["قاعدة التاريخ ليست ما تحدده هذه العلامة؛ المنطقة لها قيد خاص على أماكن الركن.","في منطقة السير بسرعة المشي يُسمح بالركن فقط في الأماكن المهيأة لذلك؛ لا تكفي مساحة خالية بجانب الطريق.","عدم إعاقة المرور شرط مهم لكنه لا يلغي اشتراط المكان المخصص.","توجد إمكانية للركن في الأماكن المخصصة؛ المنع ليس مطلقًا."],"explanation":"في منطقة السير بسرعة المشي يُسمح بالركن فقط في الأماكن المهيأة لذلك؛ لا تكفي مساحة خالية بجانب الطريق."},"q155":{"textAr":"ما الذي يحدد أولًا سرعتك عند عبور السكة؟","answersAr":["مدى الرؤية وحالة الطريق.","الحالة الفنية للمركبة.","خبرتي ومهارتي.","حد السرعة المكتوب للطريق فقط."],"answerReasonsAr":["اقترب بسرعة تمكنك من التوقف قبل السكة إذا لزم الأمر؛ ضعف الرؤية أو الانزلاق يفرضان إبطاءً مبكرًا.","سلامة المركبة ضرورية، لكنها لا تبرر سرعة لا تناسب الرؤية أمام المعبر.","الخبرة لا تلغي خطر قطار غير مرئي أو طريق زلق.","العلامة حد أقصى وليست سرعة واجبة؛ قد تكون السرعة الآمنة أقل بكثير."],"explanation":"اقترب بسرعة تمكنك من التوقف قبل السكة إذا لزم الأمر؛ ضعف الرؤية أو الانزلاق يفرضان إبطاءً مبكرًا."},"q156":{"textAr":"ما المقصود بقارعة الطريق، أي الجزء المخصص لسير المركبات؟","answersAr":["الطريق كله مع الكتف ومسار الدراجات.","الطريق كله مع الكتف ودون مسار الدراجات.","جزء سير المركبات دون كتف الطريق ومسار الدراجات."],"answerReasonsAr":["هذا يخلط الطريق بكل أجزائه بالجزء المخصص لحركة المركبات.","الكتف لا يُعد جزءًا من قارعة الطريق في هذا التعريف.","التعريف يفصل قارعة السير عن الكتف ومسار الدراجات؛ معرفة الحد مهمة لقواعد الموضع والتوقف."],"explanation":"التعريف يفصل قارعة السير عن الكتف ومسار الدراجات؛ معرفة الحد مهمة لقواعد الموضع والتوقف."},"q157":{"textAr":"متى يجب استخدام إشارة الاتجاه؟","answersAr":["عند الدوران لتغيير اتجاه السير على الطريق.","عند التوقف داخل منطقة مأهولة فقط.","لإخبار من خلفي بأن التجاوز آمن.","لمجرد أنني أسحب مركبة أخرى."],"answerReasonsAr":["الدوران يغير اتجاهك ويقطع مسارات محتملة؛ أشر مبكرًا وتحقق من السلامة قبل التنفيذ.","التوقف وحده لا يرتبط بكون المكان مأهولًا؛ الإشارة واجبة عندما تغير الاتجاه أو الموضع الجانبي.","أعلن نيتك فقط؛ لا تضمن للآخر سلامة تجاوز يعتمد على رؤيته وتقديره.","السحب لا يستدعي غمازًا مستمرًا؛ استخدمه للمناورات الفعلية."],"explanation":"الدوران يغير اتجاهك ويقطع مسارات محتملة؛ أشر مبكرًا وتحقق من السلامة قبل التنفيذ."},"q160":{"textAr":"أي عبارة صحيحة عن تقدير المسافات؟","answersAr":["نستخدم معالم مثل الأعمدة والخطوط وحجم الأجسام لتقدير المسافة.","الرؤية والطقس لا يؤثران في تقدير المسافة.","السائق الخبير لا يخطئ في تقدير المسافة إلى مركبة مقابلة."],"answerReasonsAr":["المعالم وأحجام الأجسام تعطي الدماغ دلائل على العمق؛ عند غيابها يصبح التقدير أصعب.","الضباب والظلام وضعف التباين يضعفون الدلائل البصرية وقد يسببون تقديرًا خاطئًا.","الخبرة تساعد لكنها لا تمنع الخطأ؛ اترك هامشًا ولا تتجاوز بناءً على تقدير متفائل."],"explanation":"المعالم وأحجام الأجسام تعطي الدماغ دلائل على العمق؛ عند غيابها يصبح التقدير أصعب."},"q161":{"textAr":"إلى ماذا يشير رمز المصنع؟","answersAr":["منطقة صناعية.","منطقة أنشطة في الهواء الطلق.","معلم سياحي.","نُزل للمسافرين."],"answerReasonsAr":["شكل المصنع والمدخنة يعرّف منطقة صناعية؛ توقع مركبات عمل ونقل عند الوصول.","الأنشطة الخارجية لها رموز مختلفة؛ المدخنة هنا مرتبطة بالصناعة.","هذا ليس رمز المعالم السياحية؛ اقرأ شكل المصنع المحدد.","رمز النزل يتعلق بالإقامة، وليس مبنى صناعيًا."],"explanation":"شكل المصنع والمدخنة يعرّف منطقة صناعية؛ توقع مركبات عمل ونقل عند الوصول."},"q164":{"textAr":"من يُعد مسؤولًا عن القيادة في التدريب الخاص؟","answersAr":["المتدرّب وحده.","المتدرّب والمشرف بالتساوي بوصفهما سائقين.","المشرف هو المسؤول بوصفه السائق قانونًا أثناء التدريب."],"answerReasonsAr":["وجود المتدرّب خلف المقود لا ينقل إليه وحده المسؤولية المقررة للمشرف.","النظام لا يعتبرهما سائقين متساويين؛ المشرف يُعد السائق قانونًا.","المشرف مسؤول عن الإشراف والسلامة ويُعد السائق قانونًا؛ لا يعني ذلك إعفاء المتدرّب من كل مسؤولية عن أي فعل مستقل يرتكبه."],"explanation":"المشرف مسؤول عن الإشراف والسلامة ويُعد السائق قانونًا؛ لا يعني ذلك إعفاء المتدرّب من كل مسؤولية عن أي فعل مستقل يرتكبه."},"q166":{"textAr":"تريد الانعطاف يمينًا عند التقاطع الذي تحذّر منه هذه العلامة. ما الصحيح؟","answersAr":["لا أحتاج إلى إشارة الاتجاه.","علي إعطاء الأولوية لحركة المرور القادمة من اليسار.","على القادمين من اليسار إعطائي الأولوية."],"answerReasonsAr":["حتى لو اتبع الطريق الرئيسي الانعطاف، يجب الإشارة لأنك تغير اتجاهك.","الخط الرفيع في العلامة يمثل الطريق الجانبي على اليسار، وليس طريقًا له أولوية عليك.","الخط العريض يبيّن اتجاه الطريق ذي الأولوية إلى اليمين؛ القادم من اليسار ملزم بإفساح الطريق، لكن تأكد من انتباهه."],"explanation":"الخط العريض يبيّن اتجاه الطريق ذي الأولوية إلى اليمين؛ القادم من اليسار ملزم بإفساح الطريق، لكن تأكد من انتباهه."},"q168":{"textAr":"أي عبارة صحيحة عن حد السرعة الظاهر؟","answersAr":["يستمر حتى يتغير وفق علامة سرعة أخرى أو تنظيم ينهيه.","يجوز تجاوزه إذا احتجت إلى ذلك أثناء التجاوز.","يجب السير دائمًا بالسرعة المكتوبة."],"answerReasonsAr":["التقاطع لا ينهي حد السرعة تلقائيًا؛ راقب علامات التغيير أو التنظيم الذي ينهيه.","التجاوز لا يعفي من حد السرعة؛ إذا لم يمكن إتمامه ضمن الحد وبأمان فلا تبدأه.","الرقم حد أقصى؛ الرؤية والمشاة والطقس قد تستلزم سرعة أقل."],"explanation":"التقاطع لا ينهي حد السرعة تلقائيًا؛ راقب علامات التغيير أو التنظيم الذي ينهيه."},"q169":{"textAr":"أي عبارة صحيحة عن مراقبة السائقين قليلي الخبرة للطريق؟","answersAr":["يمسحون مجالًا بصريًا أوسع من السائقين ذوي الخبرة.","يثبتون نظرهم قرب السيارة أكثر في العادة.","يحركون نظرهم بين جوانب المشهد أكثر من ذوي الخبرة."],"answerReasonsAr":["الخبرة عادةً توسع المراقبة وتساعد على توقع الخطر من بعيد.","التركيز قرب المقدمة يقلل التخطيط؛ تدرب على النظر بعيدًا مع متابعة المرايا والجوانب.","المبتدئ يميل إلى تثبيت النظر أكثر؛ المراقبة النشطة مهارة تتطور بالتدريب."],"explanation":"التركيز قرب المقدمة يقلل التخطيط؛ تدرب على النظر بعيدًا مع متابعة المرايا والجوانب."},"q173":{"textAr":"ما القاعدة الأساسية في المرور؟","answersAr":["التصرف بعناية وحذر لتجنب الحوادث.","السير بالسرعة المكتوبة دائمًا كي لا أعيق الآخرين.","التجاوز من المسار الأيمن في كل الحالات.","إطلاق المنبّه عند تجاوز حصان وراكبه دائمًا."],"answerReasonsAr":["تكييف السرعة وترك هامش أمان ومراعاة الآخرين تطبيقات لهذه القاعدة؛ الأولوية لا تلغي الحذر.","السرعة المكتوبة حد أقصى، وقد يلزم أقل منه للسلامة.","التجاوز له شروط واتجاهات محددة؛ لا توجد قاعدة تجيز اليمين دائمًا.","المنبّه قد يفزع الحصان؛ تجاوزه بهدوء وبمسافة آمنة."],"explanation":"تكييف السرعة وترك هامش أمان ومراعاة الآخرين تطبيقات لهذه القاعدة؛ الأولوية لا تلغي الحذر."},"q176":{"textAr":"ما القاعدة في التقاطع الظاهر؟","answersAr":["علي إفساح الطريق لراكب الدراجة النارية وفق قاعدة اليمين.","عليه إعطائي الأولوية لأن طريقي أكبر.","تطبق قاعدة الخروج من مدخل أو موقف."],"answerReasonsAr":["الدراجة قادمة من اليمين عند تقاطع طرق بلا تنظيم أولوية مخالف؛ أفسح لها.","عرض الطريق أو حجمه لا يمنحه أولوية تلقائيًا.","الصورة تعرض تقاطع طريقين، وليس خروجًا من موقف أو عقار؛ لا تستنتج قاعدة الخروج من ضيق الطريق وحده."],"explanation":"الدراجة قادمة من اليمين عند تقاطع طرق بلا تنظيم أولوية مخالف؛ أفسح لها."},"q178":{"textAr":"تقود بسرعة 50 على طريق مزدحم حدّه 70 فقط لأنك غير مستعجل، وتشكل خلفك طابور. هل هذا اختيار صحيح؟","answersAr":["لا؛ لا يجوز إعاقة المرور بسرعة منخفضة بلا مبرر.","نعم لأن سرعتي أعلى من 30.","لا، لأنني ملزم دائمًا بالسير بسرعة الحد المعلن.","نعم؛ السرعة شأني ما دمت دون الحد."],"answerReasonsAr":["السرعة الأقل مبررة للسلامة أو الظروف، لكن عدم الاستعجال وحده لا يبرر عرقلة الطابور؛ كيّف السير أو افسح الطريق بأمان.","تجاوز 30 لا يكفي للحكم؛ ملاءمة السرعة والسبب مهمان.","70 حد أقصى وليس سرعة مفروضة في كل حالة؛ قد يلزم إبطاء شديد للسلامة.","سلوكك يؤثر في الآخرين؛ عليك تجنب العرقلة غير الضرورية مع عدم التضحية بالسلامة."],"explanation":"السرعة الأقل مبررة للسلامة أو الظروف، لكن عدم الاستعجال وحده لا يبرر عرقلة الطابور؛ كيّف السير أو افسح الطريق بأمان."}};
